/**
 * @file ToolExecutionContext.ts
 * @description Context provided to every tool during execution.
 * Encapsulates thread identity, execution call ID, workspace directory,
 * cancellation signal, and progress streaming callbacks.
 */

/**
 * Execution context supplied to every tool execution.
 */
export interface ToolExecutionContext {
  /**
   * The unique identifier of the active thread session.
   */
  readonly threadId: string;

  /**
   * The unique identifier of this specific tool invocation generated by the model.
   */
  readonly toolCallId: string;

  /**
   * The absolute workspace root directory for resolving file paths and shell commands.
   */
  readonly workingDirectory: string;

  /**
   * Optional abort signal for immediate cancellation of in-flight operations.
   */
  readonly abortSignal?: AbortSignal | undefined;

  /**
   * Optional callback to emit streaming progress chunks (e.g. progressive shell output).
   *
   * @param chunk - The incremental text chunk emitted by the tool.
   */
  readonly emitProgress?: ((chunk: string) => void) | undefined;
}
